from lib import *
S = SS('q12')
steps = [
    step("x-max-priority=10 的队列,乱序发 a(p1) b(p5) c(p10) d(p3) e(p0) f(无优先级) g(p7) h(p5),basic_get 取出来的顺序是 c(p10)、g(p7)、b(p5)、h(p5)、d(p3)、a(p1)、e(p0)、f(无)——按优先级从大到小,同一优先级内先进先出(b 在 h 前),没写优先级的 f 按 0 算,排在同为 0 的 e 之后。", t=tl(S(1)), mark=lidx(S(1), '取出顺序'), done=lidx(S(1), '发送顺序', '同一优先级内'), kv=KV([['排序', '优先级大的先出'], ['同级', '先进先出'], ['无优先级', '按 0 算']], ['排序'])),
    step("优先级超过 x-max-priority 会被当成最大值:max-priority=5 的队列发 a(p5) b(p200) c(p6) d(p1),取出 a、b、c、d——a、b、c 都按 5 算,先进先出,d 最后。没有设 x-max-priority 的普通队列完全忽略优先级:发 a(p1) b(p9) c(p5) 取出还是 a、b、c。所以光在消息上写 priority 不够,队列必须声明过。", t=tl(S(2)), mark=lidx(S(2), '普通队列发'), done=lidx(S(2), 'max-priority=5'), kv=KV([['超过上限', '按上限算'], ['没设 x-max-priority', '优先级被忽略'], ['要点', '队列声明时必须带']], ['没设 x-max-priority'])),
    step("优先级只管“还在队列里”的消息:消费者 prefetch=20 时先发 60 条低优先级(p1),再发 1 条 HIGH(p10),HIGH 是第 21 个被处理的——前 20 条已经预取到消费者手里,插不了队;prefetch=1 时 HIGH 只排在第 2 位。要让优先级真正生效,prefetch 要小。", t=tl(S(3)), mark=lidx(S(3), 'HIGH 是第 21 个', 'HIGH 是第 2 个'), done=lidx(S(3), 'prefetch=20'), b=bars([['prefetch=20 时 HIGH 的位置', 21, '第 21 个'], ['prefetch=1 时 HIGH 的位置', 2, '第 2 个']], 21, mark=[0], done=[1]), kv=KV([['已投递给消费者的', '不再重排'], ['prefetch=20', 'HIGH 第 21'], ['prefetch=1', 'HIGH 第 2']], ['已投递给消费者的'])),
    step("代价:发布 + basic_get 取空 20000 条(随机优先级,3 轮中位数)。不设优先级:发布 510 ms、取完 1570 ms;x-max-priority=10:517 ms、1724 ms,开销很小;x-max-priority=255:发布 1218 ms、取完 6108 ms,约为不设时的 2.4 倍和 3.9 倍。优先级档数越多,内部要维护的结构越多。", t=tl(S(4)), mark=lidx(S(4), '=255'), done=lidx(S(4), '不设', '=10'), b=bars([['不设 取完', 1570, '1570 ms'], ['max-priority=10 取完', 1724, '1724 ms'], ['max-priority=255 取完', 6108, '6108 ms']], 6108, mark=[2], done=[0, 1]), kv=KV([['10 档', '开销 +10% 左右'], ['255 档', '取完 3.9 倍'], ['建议', '档数只用需要的']], ['255 档'])),
    step("空队列的内存也不一样:不设优先级的队列 14008 字节,x-max-priority=10 的 56840 字节,x-max-priority=255 的 1152088 字节(约 1.1 MB)——每多一档就多一份内部结构。队列很多的系统里,每个队列都开 255 档会白白吃掉很多内存。", t=tl(S(5)), mark=lidx(S(5), '空队列内存'), done=lidx(S(5), '空队列内存'), b=bars([['不设', 14008, '14008 B'], ['max-priority=10', 56840, '56840 B'], ['max-priority=255', 1152088, '1152088 B']], 1152088, mark=[2], done=[0, 1]), kv=KV([['不设', '14 KB'], ['10 档', '57 KB'], ['255 档', '1.1 MB']], ['255 档'])),
    step("quorum 队列在 4.3.6 里的优先级:声明时带 x-max-priority 直接被拒(406 PRECONDITION_FAILED invalid arg),但不带也支持优先级,而且是完整的排序而不是只分高低两档:依次发优先级 1、9、3、5、2、10、0、7、4、6、8、12、200、5、5,取出的顺序是 200、12、10、9、8、7、6、5(序号 3、13、14,先进先出)、4、3、2、1、0。", t=tl(S(6)), mark=lidx(S(6), 'quorum + x-max-priority=5', 'quorum 队列取出'), done=lidx(S(6), '依次发优先级', '优先级从大到小排好'), kv=KV([['x-max-priority', 'quorum 队列不接受(406)'], ['排序', '完整的优先级顺序'], ['同级', '先进先出']], ['排序'])),
]
A = mkartq('q12', 12, 'RabbitMQ,优先级队列,x-max-priority,真实验证,动画演示',
    '在 RabbitMQ 4.3.6 上实测优先级队列:按优先级从大到小取出,同级先进先出;超出上限按上限算,没声明的队列忽略优先级;已预取的消息插不了队(prefetch=20 时 HIGH 排第 21);255 档比不设慢到 3.9 倍、空队列占 1.1 MB;quorum 队列按完整优先级排序但不接受 x-max-priority。',
    '给消息加 priority 就能让重要的先被处理吗?为什么有时高优先级的消息还是排在后面?开 255 档优先级要付出多少代价?quorum 队列呢?这篇在 RabbitMQ 4.3.6 上逐项验证。',
    [('第 21 个', 'prefetch=20 时后发的高优先级消息被处理的位置(prefetch=1 时是第 2 个)'), ('3.9 倍', 'x-max-priority=255 比不设优先级时 basic_get 取完 20000 条的耗时'), ('1.1 MB', 'x-max-priority=255 的空队列占用的内存(不设时 14 KB)')],
    [('排序规则', '<p>队列声明时带 <code>x-max-priority</code>,消息带 <code>priority</code> 属性。取出时按优先级降序,同级先进先出,没写优先级的按 0 算。</p>'),
     ('上限与声明', '<p>消息优先级超过上限的按上限算;没声明 <code>x-max-priority</code> 的队列完全不看优先级。</p>'),
     ('预取的局限', '<p>优先级只能重排还在队列里的消息。已经预取给消费者的消息不会被后来的高优先级消息超过,所以要让优先级有意义,消费者的 prefetch 要小。</p>'),
     ('取出的耗时', '<p>优先级档数越多,取出越慢:取 20000 条,255 档的耗时是不设优先级时的 3.9 倍,10 档的开销只有一成左右。</p>'),
     ('内存', '<p>空队列的内存:不设 14 KB、10 档 57 KB、255 档 1.1 MB,每多一档就多一份内部结构。</p>'),
     ('quorum 队列', '<p>声明 quorum 队列时不能带 <code>x-max-priority</code>(406),但消息上的 priority 照样被排序,实测是完整的降序、同级先进先出。(这与我印象中“quorum 只有高低两档”的说法不同,以 4.3.6 实测为准。)</p>')],
    steps,
    [ENV_Q + '。第一、二、六节用 basic_get 取出观察顺序;第三节消费者每条处理 10 ms,第一个线程先发 60 条低优先级再发 HIGH;第四节 3 轮取中位数,优先级随机(固定随机种子);空队列内存来自 rabbitmqctl list_queues memory',
     '没有验证:有消息时各档的内存占用;多个消费者下的优先级效果;优先级与 TTL / 死信 / 长度限制组合;stream 队列没有优先级;quorum 队列优先级的内部实现与性能代价;更长时间运行后的稳定性'],
    '优先级队列')
